sys_script_include.script:
var CheckManager = Class.create();
CheckManager.prototype = Object.extendsObject(global.AbstractAjaxProcessor, { // <-- Adicionado o prefixo global. aqui

    getAvailableManagers: function() {
        // --- PARTE 1: BUSCAR MEMBROS DO GRUPO ---
        var managerIdsFromGroups = [];
        var grMembers = new GlideRecord('sys_user_grmember');

        // Nome exato do seu grupo de gerentes
        var managerGroupName = 'Base Allocation Managers'; 

        grMembers.addQuery('group.name', managerGroupName);
        grMembers.query();

        while (grMembers.next()) {
            managerIdsFromGroups.push(grMembers.getValue('user'));
        }

        // Se o grupo estiver vazio, impede de quebrar a tela retornando um filtro nulo
        if (managerIdsFromGroups.length == 0) {
            return "sys_idINjavascript:null";
        }

        // --- PARTE 2: BUSCAR GERENTES JÁ ALOCADOS ---
        var occupiedManagers = [];
        var grBase = new GlideRecord('x_1902784_base_a_0_base_registration');
        grBase.addNotNullQuery('manager');
        grBase.query();

        while (grBase.next()) {
            occupiedManagers.push(grBase.getValue('manager'));
        }

        // --- PARTE 3: MONTAR O FILTRO DA LUPINHA ---
        var filterString = "active=true^sys_idIN" + managerIdsFromGroups.join(',');

        if (occupiedManagers.length > 0) {
            filterString += "^sys_idNOT IN" + occupiedManagers.join(',');
        }

        return filterString;
    },

    type: 'CheckManager'
});
